sp_widget.client_script:
api.controller = function () {
    var c = this;

    if (c.data.request_state && !c.data.requestState) {
        c.data.requestState = c.data.request_state;
    }
};

sp_widget.script:
(function () {
    var sysId = $sp.getParameter('sysparm_id');
    data.short_description = '';
    data.request_state = '';

    if (sysId) {
        var gr = new GlideRecord('sc_request');
        gr.addQuery('sys_id', sysId);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            data.short_description = gr.getValue('short_description') + '';
            data.request_state = gr.getDisplayValue('request_state') + '';
        }
    }
})();
